//go:build amd64

package floats

// The AVX2+FMA kernel of MulAddRows (mulrows.go), generated by go-asmgen
// (mulrows_amd64_gen.go) into mulrows_amd64.s: blocks of 16, 4 and 1 columns, the block
// of dst held in registers across all the rows, for a CPU with the AVX2+FMA of the other
// kernels (hasAVX2FMA, kernels_amd64.go); the portable math.FMA loop otherwise, with the
// same bits. The caller guarantees rows >= 1, len(dst) >= 1 and the lengths of a and b.
// No kernel keeps a pointer: go:noescape.
//
//go:noescape
func mulAddRowsAVX2(dst, a []float64, lda int, b []float64, ldb int, rows int)

func mulAddRows(dst, a []float64, lda int, b []float64, ldb int, rows int) {
	if hasAVX2FMA {
		mulAddRowsAVX2(dst, a, lda, b, ldb, rows)
		return
	}
	mulAddRowsRef(dst, a, lda, b, ldb, rows)
}
